const ozExam5Orta = <(String, String, List<String>, String)>[
  ('Bir sözcükten sonra gelen "de"nin bağlaç mı ek mi olduğunu anlamak için en güvenilir yol hangisidir?', 'Onu cümleden çıkarıp cümlenin hâlâ kurallı kalıp kalmadığına bakmak', ['Kendinden önceki sözcüğün ünlüsüne uyup uymadığına bakmak', 'Cümlenin sonunda mı ortasında mı yer aldığına bakmak', 'Kendinden önce virgül bulunup bulunmadığına bakmak'], 'Bağlaç olan "de" çıkarılınca cümle bozulmaz, yalnız anlam daralır. Ek olan "-de" çıkarılınca cümle bozulur. Ünlü uyumu ölçüt olamaz, çünkü bağlaç da "de/da" biçiminde uyuma girer.'),
  ('Aşağıdaki cümlelerin hangisinde "ki" bağlaç olduğu hâlde yanlışlıkla bitişik yazılmıştır?', 'Öyle yoruldumki yemek bile yiyemedim.', ['Duydum ki yeni bir iş bulmuşsun.', 'Masadaki kitabı bana bir dakika uzatır mısın?', 'Benim kalemim kırıldı, seninki yazıyor mu?'], 'İki yargıyı bağlayan "ki" bağlaçtır ve ayrı yazılır: "Öyle yoruldum ki". "Masadaki" ve "seninki" sözlerindeki "-ki" ektir, bitişik yazılması doğrudur.'),
  ('Bağlaç olan "ki" kural olarak ayrı yazılır; ancak kalıplaşmış bazı sözcüklerde bitişik yazılır. Aşağıdakilerin hangisi bu kalıplaşmış sözcüklerden biri değildir?', 'demekki', ['belki', 'sanki', 'hâlbuki'], '"Belki, sanki, çünkü, hâlbuki, mademki, oysaki" gibi sözcükler kalıplaştığı için bitişik yazılır. "Demek ki" ise kalıplaşmamıştır ve ayrı yazılmalıdır.'),
  ('Aşağıdakilerin hangisi bitişik yazılması gerekirken ayrı yazılmıştır?', 'hiç bir', ['her şey', 'bir şey', 'hiç kimse'], '"Hiçbir" bitişik yazılır. "Her şey", "bir şey" ve "hiç kimse" ise kurala göre ayrı yazılır.'),
  ('Aşağıdaki sözcük çiftlerinin hangisinde iki yazım da doğrudur?', 'birkaç - birçok', ['herbir - birkaç', 'birçok - pekçok', 'hiçbir - herşey'], '"Birkaç" ve "birçok" bitişik yazılır. "Her bir", "pek çok" ve "her şey" ise ayrı yazılmalıdır.'),
  ('Aşağıdakilerin hangisinde tezlik, süreklilik ya da yeterlik bildiren birleşik fiil yanlış yazılmıştır?', 'yazı verdi', ['bakakaldı', 'gidedursun', 'okuyabilir'], 'Tezlik, süreklilik, yeterlik ve yaklaşma bildiren birleşik fiiller bitişik yazılır: "yazıverdi, bakakaldı, gidedursun, okuyabilir".'),
  ('Aşağıdaki cümlelerin hangisinde hem bulunma eki olan "-da" hem de bağlaç olan "da" vardır?', 'Sınıfta oturanlar da sınavı kazandı.', ['Biz de bu akşam sizinle sinemaya geliriz.', 'Parkın yanından yürüyerek geçtik.', 'Bu soruyu o da çözemedi.'], '"Sınıfta" sözcüğündeki -ta bulunma ekidir; "oturanlar da" sözündeki ayrı yazılmış "da" ise bağlaçtır. Öteki cümlelerde ya yalnız bağlaç vardır ya da hiçbiri yoktur.'),
  ('Aşağıdaki sözcüklerden hangisi kurala göre ayrı yazılır?', 'çamaşır makinesi', ['hanımeli', 'Kızılırmak', 'başöğretmenlik'], 'Belirtisiz isim tamlaması kuruluşundaki araç adları ayrı yazılır: "çamaşır makinesi". Bitki adı "hanımeli", yer adı "Kızılırmak" ve unvan "başöğretmen" bitişiktir.'),
  ('Aşağıdaki cümlelerin hangisinde yön bildiren sözcüğün büyük harfle yazılması doğrudur?', 'Doğu Anadolu\'nun yaylaları yazın serin olur.', ['Kuşlar kışın sıcak bölgelere, Güneye göç eder.', 'Odanın tek penceresi Batıya bakıyordu.', 'Rüzgâr bu sabah Kuzeyden esiyor.'], 'Yön adları bir özel adın parçası olduğunda büyük harfle başlar: Doğu Anadolu. Yalnız yön bildiren güney, batı, kuzey sözcükleri küçük harfle yazılmalıdır.'),
  ('Aşağıdaki sıra sayılarından hangisinin yazımı yanlıştır?', '8\'nci', ['5\'inci', '3\'üncü', '10.'], 'Rakamla yazılan sıra sayılarına ek, kesmeyle ve tam biçimiyle getirilir: 8\'inci. "8\'nci" yazımı yanlıştır. Rakamdan sonra nokta konarak da sıra sayısı gösterilebilir: 10.'),
  ('Rakamla yazılmış bir yıla bulunma eki getirilirken hangisi doğrudur?', '1453\'te İstanbul fethedildi.', ['1453\'de İstanbul fethedildi.', '1453 de İstanbul fethedildi.', '1453te İstanbul fethedildi.'], 'Rakamla yazılan sayılara ekler kesmeyle getirilir ve sayının okunuşuna uyar. "Bin dört yüz elli üç" sert ünsüzle bittiği için ek "-te" olur.'),
  ('Aşağıdaki cümlelerin hangisinde büyük harfin kullanımı yanlıştır?', 'Annem her Pazar günü semt pazarına gider.', ['Yıllık toplantı 3 Mart 2025 Pazartesi günü saat onda yapılacak.', 'Akdeniz\'in kıyıları turistlerle doluydu.', 'Yazın Karadeniz\'de yayla gezisine çıktık.'], 'Belirli bir tarih bildirmeyen gün adları küçük harfle yazılır: "her pazar günü". Belirli tarihteki "Pazartesi", yer adları "Akdeniz" ve "Karadeniz" ise büyük harfle başlar.'),
  ('Rakamla yazılmış bir yüzde ifadesine iyelik eki getirildiğinde hangisi doğru yazılmıştır?', 'Öğrencilerin %40\'ı sınavı geçti.', ['Öğrencilerin 40%\'ı sınavı geçti.', 'Öğrencilerin %40ı sınavı geçti.', 'Öğrencilerin % 40\'ı sınavı geçti.'], 'Türkçede yüzde işareti sayının önüne, arada boşluk bırakılmadan yazılır; sayıya gelen ek de kesmeyle ayrılır: %40\'ı.'),
  ('"Yarın Ankara, Eskişehir ( ) öbür gün İzmir, Manisa ( ) Aydın\'a uğrayacağız." cümlesinde ayraç içindeki yerlere sırasıyla hangi işaretler gelmelidir?', 'noktalı virgül, virgül', ['virgül, noktalı virgül', 'iki nokta, virgül', 'virgül, iki nokta'], 'Virgülle ayrılmış eş görevli öge takımlarını birbirinden ayırmak için noktalı virgül kullanılır. Takımın içindeki adlar ise virgülle ayrılır.'),
  ('"Yunus Emre (1240? - 1320)" yazımında ayraç içindeki soru işareti neyi gösterir?', 'Bilginin kesin olmadığını, şüpheyle verildiğini', ['Yazarın okura doğrudan bir soru yönelttiğini', 'Tarihin yanlış olduğunu kesin olarak', 'Alay ya da küçümsemeyi'], 'Bilinmeyen ya da kesin olmayan bir bilginin yanına soru işareti konur. Burada doğum yılının kesin bilinmediği belirtilmektedir.'),
  ('Aşağıdaki cümlelerin hangisinde kısa çizgi, "ile ... arasında" anlamı vermek için kullanılmıştır?', 'Ankara-İstanbul hızlı tren seferleri yeniden başladı.', ['Bu sorunun - en azından bana göre - çözümü sanıldığından kolay.', 'Kitabın ilk cümlesi "Bir varmış, bir yokmuş" idi.', 'Toplantı saat 14.30\'da başlayacak.'], 'İki yer adı arasına konan kısa çizgi, "Ankara ile İstanbul arasında" anlamı verir. İkinci seçenekte çizgi ara sözü ayırmaktadır.'),
  ('Aşağıdaki cümlelerin hangisinde ara söz, kurala uygun biçimde işaretlenmiştir?', 'Kardeşim, en küçüğümüz, bu yıl üniversiteyi bitirdi.', ['Kardeşim en küçüğümüz; bu yıl üniversiteyi derece ile bitirdi.', 'Kardeşim: en küçüğümüz, bu yıl üniversiteyi bitirdi.', 'Kardeşim en küçüğümüz bu yıl, üniversiteyi bitirdi.'], 'Cümlenin akışını kesen ara söz ya da ara cümle, iki virgül ya da iki kısa çizgi arasına alınır. Doğru seçenekte "en küçüğümüz" iki virgülle ayrılmıştır.'),
  ('"Az" sözcüğünün "-cık" ekiyle "azıcık", "bir" sözcüğünün "-cik" ekiyle "biricik" biçimini alması hangi ses olayıdır?', 'Ünlü türemesi', ['Ünlü düşmesi', 'Ünsüz düşmesi', 'Ünsüz türemesi'], '"Azıcık" ve "biricik" sözcüklerinde kökte ve ekte bulunmayan bir ünlü (ı, i) ortaya çıkmıştır; bu ünlü türemesidir.'),
  ('"Küçük" sözcüğüne "-cük" eki getirilince "küçücük" olmasında hangi ses olayı görülür?', 'Ünsüz düşmesi', ['Ünlü düşmesi', 'Ünsüz türemesi', 'Ünlü daralması'], 'Küçük+cük birleşiminde kökün sonundaki "k" ünsüzü düşmüştür: küçücük. Aynı olay "ufacık" sözcüğünde de görülür.'),
  ('"His" sözcüğü "etmek" ile birleşince "hissetmek" olması hangi ses olayıdır?', 'Ünsüz türemesi', ['Ünsüz düşmesi', 'Ünsüz yumuşaması', 'Kaynaştırma'], 'Arapçadan gelen bazı sözcüklerde ünlüyle başlayan bir ek ya da fiil geldiğinde son ünsüz ikizleşir: his-hissetmek, af-affetmek.'),
  ('Sözcükte yan yana duran iki ünsüzün yer değiştirmesine göçüşme denir. Aşağıdakilerden hangisi göçüşmeye örnektir?', 'yarpak → yaprak', ['ağız → ağzı', 'ne için → niçin', 'kitap+ta → kitapta'], 'Eski Türkçedeki "yarpak" sözcüğünde r ile p yer değiştirerek "yaprak" biçimi oluşmuştur. "Toprak" da "torpak" biçiminden göçüşmeyle gelmiştir.'),
  ('"Gözlükçüler" sözcüğünün kökü ve gövdesi aşağıdakilerin hangisinde doğru verilmiştir?', 'Kök: göz; gövde: gözlükçü', ['Kök: gözlük; gövde: gözlükçü', 'Kök: göz; gövde: gözlükçüler', 'Kök: gözlükçü; gövde: gözlük'], 'Sözcüğün anlamlı en küçük parçası "göz" köktür. Yapım ekleri alarak oluşan "gözlükçü" gövdedir; "-ler" çekim eki olduğu için gövdeye dahil edilmez.'),
  ('Aşağıdaki sözcüklerin hangisinin kökü fiildir?', 'yazı', ['gözcü', 'taşlık', 'başlık'], '"Yazı" sözcüğü "yaz-" fiil köküne "-ı" yapım eki getirilerek türetilmiştir. "Gözcü, taşlık, başlık" ise isim kökünden türemiştir.'),
  ('"Sulamak" sözcüğünde "su" köküne getirilen "-la" eki için hangisi doğrudur?', 'Addan fiil yapım ekidir.', ['Fiilden ad yapım ekidir.', 'Addan ad yapım ekidir.', 'Sözcüğe çoğul anlamı katan bir çekim ekidir.'], '"Su" bir addır; "-la" ekiyle "sula-" fiili türetilmiştir. Böylece addan fiil yapılmıştır.'),
  ('Aşağıdaki cümlelerin hangisinde "ile" bağlaç olarak kullanılmıştır?', 'Ayşe ile Elif bu yıl aynı sınıfa düştü.', ['Mektubu eski bir kurşun kalemle yazdı.', 'Okula otobüsle gidiyor.', 'Büyük bir sevinçle haberi verdi.'], '"Ve" yerine kullanılabilen "ile" bağlaçtır: "Ayşe ve Elif". Öteki cümlelerde "ile" araç ya da durum bildiren bir edattır.'),
  ('Aşağıdaki cümlelerin hangisinde "çok" sözcüğü bir sıfatı derece bakımından niteleyen miktar zarfıdır?', 'Bu kumaş çok yumuşak.', ['Bu yaz çok kitap okudu.', 'Bahçede çok ağaç var.', 'Çok insan bu yolu kullanır.'], '"Çok yumuşak" sözünde "çok", "yumuşak" sıfatının derecesini belirten bir zarftır. Öteki cümlelerde bir adın miktarını belirttiği için belgisiz sıfattır.'),
  ('Aşağıdaki cümlelerin hangisinde zarf-fiil kullanılmamıştır?', 'Okuduğum kitabı arkadaşıma verdim.', ['Eve gelince seni ararım.', 'Gülerek odaya girdi.', 'Kahvaltımızı yapıp hemen yola çıktık.'], '"Okuduğum" sözcüğü "-dik" ekiyle kurulmuş ve "kitap" adını niteleyen bir sıfat-fiildir. Öteki cümlelerde "-ince, -erek, -ip" zarf-fiil ekleri vardır.'),
  ('"Ben eve dönerken yağmur başladı." cümlesindeki fiilimsi cümleye hangi anlamı katmaktadır?', 'Zaman', ['Amaç', 'Koşul', 'Karşılaştırma'], '"-erken" zarf-fiili, yağmurun başlama zamanını belirtir: eve dönme sırasında.'),
  ('Aşağıdaki cümlelerin hangisinde "-mış" eki sıfat-fiil eki olarak kullanılmıştır?', 'Haşlanmış yumurtayı soydu.', ['Yumurta haşlanmış.', 'Annem yumurtayı haşlamış.', 'Ben bu yumurtayı haşlamışım.'], '"Haşlanmış" sözcüğü "yumurta" adını niteleyerek sıfat görevi almıştır. Öteki cümlelerde "-mış" duyulan geçmiş zaman ekidir ve sözcük çekimli fiildir.'),
  ('Aşağıdaki fiillerden hangisi dönüşlü çatıdadır?', 'giyindi', ['giyildi', 'giydirdi', 'giydiler'], 'Öznenin yaptığı eylemden kendisinin etkilendiği fiiller dönüşlüdür: giyindi = kendini giydirdi. "Giyildi" edilgen, "giydirdi" ettirgendir.'),
  ('"Yarın sabah erkenden yola çıkıyoruz." cümlesinde hangi kip, başka bir zaman anlamında kullanılmıştır?', 'Şimdiki zaman, gelecek zaman yerine', ['Geniş zaman, öğrenilen geçmiş zaman yerine', 'Gelecek zaman, şimdiki zaman yerine', 'Geçmiş zaman, geniş zaman yerine'], '"-yor" eki şimdiki zaman bildirir; ancak "yarın sabah" sözü eylemin gelecekte yapılacağını gösterir. Bu bir zaman kaymasıdır.'),
  ('Aşağıdaki fiillerden hangisi dilek kiplerinden biriyle çekimlenmiştir?', 'okusak', ['okuyacak', 'okuyor', 'okumuş'], '"-sa/-se" şart (dilek-koşul) kipidir ve dilek kipleri arasında yer alır. Öteki üç fiil haber kipleriyle çekimlenmiştir.'),
  ('"Çocuk elma yedi." ile "Çocuk elmayı yedi." cümleleri arasındaki öğe farkı nedir?', 'Birincide belirtisiz, ikincide belirtili nesne vardır.', ['Birincide nesne yoktur, ikincide vardır.', 'Birincide özne yoktur, ikincide vardır.', 'İkisinde de nesne belirtisizdir, yalnız yüklemler farklıdır.'], '"Ne yedi?" sorusunun yanıtı her iki cümlede de nesnedir. "-ı" eki almış "elmayı" belirtili, ek almamış "elma" belirtisiz nesnedir.'),
  ('"Bahçedeki ağaçların yaprakları sarardı." cümlesinde özne kaç sözcükten oluşur?', 'Üç', ['Bir', 'İki', 'Dört'], 'Yükleme "ne sarardı?" sorusu sorulunca "Bahçedeki ağaçların yaprakları" öbeğinin tamamı yanıt olarak gelir. Tamlama ve sıfat öbekleri bölünmeden tek öğe sayılır.'),
  ('"Sokaklar sabah erkenden temizlendi." cümlesindeki "sokaklar" sözcüğü için hangisi doğrudur?', 'Edilgen bir yüklemin sözde öznesidir.', ['Cümlenin belirtisiz nesnesidir.', 'Yer bildiren bir dolaylı tümleçtir.', 'Gerçek öznedir; temizleme eylemini kendisi yapmıştır.'], 'Yüklem edilgen çatıdadır; temizleme işini yapan belli değildir. Eylemden etkilenen "sokaklar" öznenin yerini tuttuğu için sözde öznedir.'),
  ('"Annem dün pazardan taze sebze aldı." cümlesi kaç öğeden oluşur?', 'Beş', ['Dört', 'Üç', 'Altı'], 'Annem (özne) / dün (zarf tümleci) / pazardan (dolaylı tümleç) / taze sebze (belirtisiz nesne) / aldı (yüklem): beş öğe vardır.'),
  ('Aşağıdaki cümlelerden hangisi yapı bakımından birleşik bir cümledir?', 'Eve gelince seni ararım.', ['Kardeşim bu sabah okula gitti.', 'Kapıyı açtı, içeri girdi.', 'Hava güzeldi ama dışarı çıkmadık.'], '"Eve gelince" zarf-fiil öbeği yan cümle kurmuştur; yan cümle ile temel cümle birleşik cümleyi oluşturur. Üçüncü seçenek sıralı, dördüncüsü bağlı cümledir.'),
  ('"Ah o eski bayramlar..." cümlesi için hangisi doğrudur?', 'Yüklemi söylenmemiş, eksiltili bir cümledir.', ['Yüklemi başta olduğu için devrik bir cümledir.', 'İki yüklemli, sıralı bir cümledir.', 'Fiil cümlesidir, yüklemi "ah" sözcüğüdür.'], 'Yüklemi bulunmayan, anlamı sezdirilen ve sonuna çoğunlukla üç nokta konan cümleler eksiltili cümledir.'),
  ('Aşağıdaki cümlelerin hangisi bağlaçla bağlanmış (bağlı) bir cümledir?', 'Çok yorgundu fakat işini bitirdi.', ['Yorgunluktan gözleri ister istemez kapanıyordu.', 'Yorulunca biraz dinlendi.', 'Yorgundu, erkenden yattı.'], 'İki bağımsız cümle "fakat" bağlacıyla birbirine bağlanmıştır. "Yorulunca" yan cümle kurduğu için birleşik, virgülle ayrılan son seçenek ise sıralı cümledir.'),
  ('"Ona güveniyor ve seviyordum." cümlesindeki anlatım bozukluğunun nedeni hangisidir?', 'İki yüklemin ortak kullanılan öğesi farklı ek gerektiriyor.', ['Cümlede gereksiz bir sözcük kullanılmıştır.', 'Cümlenin yüklemi etken değil, edilgen çatıda kurulmuştur.', 'Cümlede anlamca çelişen iki sözcük vardır.'], '"Güvenmek" yönelme hâli ister (ona), "sevmek" ise belirtme hâli ister (onu). Ortak öğe ikinci yükleme uymadığı için "onu da seviyordum" eklenmelidir.'),
  ('"Proje hazırlandı ve kurula sundu." cümlesindeki bozukluk hangi tür bir yanlışlıktan kaynaklanır?', 'Çatı uyumsuzluğu', ['Gereksiz sözcük', 'Sözcüğün yanlış anlamda kullanılması', 'Noktalama yanlışlığı'], 'Birinci yüklem edilgen (hazırlandı), ikinci yüklem etkendir (sundu). Ortak özneye uyması için "sunuldu" denmelidir.'),
  ('"Her yıl yüz binlerce ağaç dikilerek ormanlarımız tahrip ediliyor." cümlesindeki anlatım bozukluğu hangisidir?', 'Sözcüğün yanlış anlamda kullanılması', ['Özne-yüklem uyumsuzluğu', 'Gerekli bir ekin eksik bırakılması', 'Gereksiz sözcük kullanımı'], 'Ağaç dikmek ormanları büyütür; "tahrip etmek" (yıkmak, harap etmek) sözcüğü anlama uymaz. "Genişletiliyor" gibi bir sözcük kullanılmalıdır.'),
  ('"Bu sorunun çözülmesi mümkün olabilir." cümlesinde anlatım bozukluğuna yol açan nedir?', 'Olasılık anlamının iki kez verilmesi', ['Yüklemin olumsuz kullanılması', 'Öznenin cümlede hiç bulunmaması', 'Cümlenin devrik olması'], '"Mümkün" sözcüğü de "-ebilir" eki de olasılık bildirir. Biri yeterlidir: "çözülmesi mümkündür" ya da "çözülebilir".'),
  ('Ayşe, Burak ve Cem\'den biri pastayı yemiştir. Ayşe "Pastayı Burak yedi.", Burak "Pastayı Cem yedi.", Cem "Ben yemedim." diyor. Üçünden yalnız biri yalan söylediğine göre pastayı kim yemiştir?', 'Burak', ['Ayşe', 'Cem', 'Belirlenemez'], 'Burak ile Cem\'in sözleri birbirine ters olduğundan biri yalandır; tek yalancı bu ikisinden biridir ve Ayşe doğru söyler. Ayşe\'ye göre pastayı Burak yemiştir; bu durumda yalnız Burak yalan söylemiş olur.'),
  ('30 kişilik bir sınıfta 18 öğrenci gözlüklü, 20 öğrenci kızdır. Bu sınıfta gözlüklü kız öğrenci sayısı en az kaçtır?', '8', ['2', '10', '12'], 'Gözlüklüler ile kızların toplamı 38\'dir; sınıf 30 kişi olduğundan en az 38−30 = 8 kişi iki grupta birden bulunmak zorundadır.'),
  ('Bir toplulukta insanların %60\'ı çay, %50\'si kahve içmektedir. Hiçbirini içmeyenler %20 olduğuna göre ikisini birden içenler topluluğun yüzde kaçıdır?', '%30', ['%10', '%20', '%40'], 'En az birini içenler %80\'dir. %60 + %50 − x = %80 eşitliğinden x = %30 bulunur.'),
  ('45 kişilik bir grupta 27 kişi yüzme, 22 kişi tenis biliyor; 9 kişi ikisini de biliyor. Bu iki spordan yalnız birini bilen kaç kişi vardır?', '31', ['40', '36', '22'], 'Yalnız yüzme bilen 27−9 = 18, yalnız tenis bilen 22−9 = 13 kişidir. Toplam 18+13 = 31.'),
  ('Bir sınıfta herkes A ya da B projelerinden en az birinde görev almıştır. A\'da görev alan her öğrenci B\'de de görev almıştır. A\'da 12, B\'de 20 öğrenci olduğuna göre sınıf kaç kişidir?', '20', ['32', '12', '8'], 'A kümesi B\'nin alt kümesidir; birleşim B\'nin kendisidir. Sınıfta 20 öğrenci vardır.'),
  ('"Bazı öğrenciler sporcudur. Bütün sporcular disiplinlidir." önermelerine göre hangisi kesinlikle doğrudur?', 'Bazı öğrenciler disiplinlidir.', ['Bütün öğrenciler disiplinlidir.', 'Bütün disiplinliler sporcudur.', 'Hiçbir disiplinli öğrenci değildir.'], 'Sporcu olan öğrenciler, bütün sporcular disiplinli olduğu için disiplinlidir. Bu da en az bazı öğrencilerin disiplinli olduğunu gösterir.'),
  ('"Bütün doktorlar üniversite mezunudur. Selin üniversite mezunudur." önermelerinden Selin hakkında hangisi söylenebilir?', 'Doktor olup olmadığı belirlenemez.', ['Selin kesinlikle doktordur.', 'Selin kesinlikle doktor değildir.', 'Selin\'in mezun olduğu fakülte tıp fakültesidir.'], 'Doktorlar, üniversite mezunlarının yalnız bir bölümüdür. Selin mezunlar kümesinde olsa da doktorlar alt kümesinde olup olmadığı bilinmez.'),
  ('Bir tam sayının 4\'e bölünmesi, o sayının çift olması için nasıl bir koşuldur?', 'Yeterli ama gerekli olmayan bir koşul', ['Gerekli olan ama tek başına yeterli olmayan bir koşul', 'Hem gerekli hem yeterli bir koşul', 'Ne gerekli ne de yeterli bir koşul'], '4\'e bölünen her sayı çifttir, yani koşul yeterlidir. Ama 6 gibi 4\'e bölünmeyen çift sayılar da vardır; bu yüzden koşul gerekli değildir.'),
  ('"Erken kalkarsa kahvaltı yapar; kahvaltı yaparsa derste dikkatli olur." Bugün Mert\'in derste dikkatli olmadığı biliniyorsa hangisi kesindir?', 'Mert bugün erken kalkmamıştır.', ['Mert bugün erken kalkmış, kahvaltı yapmamıştır.', 'Mert bugün kahvaltı yapmış ama derse geç kalmıştır.', 'Mert derslerde hiçbir zaman dikkatli olmaz.'], 'Dikkatli olmadıysa kahvaltı yapmamıştır (karşıt ters); kahvaltı yapmadıysa erken kalkmamıştır. Zincirleme karşıt tersle sonuca varılır.'),
  ('İki otobüs aynı duraktan biri 15, öteki 20 dakikada bir kalkmaktadır. Saat 07.10\'da birlikte kalktıklarına göre saat 12.00\'ye kadar kaç kez daha birlikte kalkarlar?', '4', ['5', '3', '10'], 'EKOK(15, 20) = 60 dakika olduğundan saat başlarından 10 dakika sonra birlikte kalkarlar: 08.10, 09.10, 10.10 ve 11.10. 12.10 aralığın dışındadır.'),
  ('"Altın yüzük" ve "tahta masa" örneklerindeki tamlamaların ortak özelliği hangisidir?', 'Tamlayan malzemeyi bildirir, iki öğe de ek almaz.', ['Tamlayan ilgi eki, tamlanan iyelik eki almıştır.', 'Tamlayan bir sıfat-fiildir.', 'Tamlanan yalnızca iyelik eki almıştır.'], 'Bunlar takısız isim tamlamasıdır: tamlayan bir maddeyi (altın, tahta) bildirir, sıfat gibi davranır ve öğeler ek almaz.'),
  ('"Okulun bahçe kapısı" söz öbeği nasıl bir tamlamadır?', 'Zincirleme isim tamlaması', ['Takısız isim tamlaması', 'Sıfat tamlaması', 'Belirtisiz isim tamlamasının tek başına kullanımı'], '"Bahçe kapısı" belirtisiz bir tamlamadır; bu öbek, "okulun" tamlayanına tamlanan olmuştur. Tamlayanı ya da tamlananı tamlama olan yapılar zincirleme isim tamlamasıdır.'),
  ('"Kitabını getirdin mi?" cümlesindeki "kitabını" sözcüğüyle ilgili hangisi doğrudur?', 'Tamlayanı düşmüş bir tamlamanın parçasıdır.', ['Belirtisiz bir isim tamlamasının tamlayanıdır.', 'Bir sıfat tamlamasının sıfatıdır.', 'Ek almamış yalın bir addır.'], '"Kitabın" sözündeki ikinci tekil kişi iyelik eki, "senin kitabın" tamlamasını gösterir. Tamlayan söylenmemiş ama anlamca sezdirilmektedir.'),
  ('Belirtisiz isim tamlamasında tamlayan ile tamlanan arasına başka bir sözcük girebilir mi?', 'Giremez; girerse tamlama türü değişir.', ['Girebilir; araya giren sözcük tamlamanın türünü değiştirmez.', 'Yalnız sayı sıfatı girebilir.', 'Yalnız bağlaç girebilir.'], '"Kapı kolu" belirtisiz tamlamasının arasına bir sıfat girerse tamlayan ek alır: "kapının eski kolu" belirtili tamlama olur.'),
  ('"Annemin yaptığı börek" söz öbeğinde temel tamlama türü hangisidir?', 'Sıfat tamlaması', ['Belirtili isim tamlaması', 'Takısız isim tamlaması', 'Belirtisiz isim tamlaması'], '"Annemin yaptığı" sıfat-fiil öbeği "börek" adını nitelemektedir; temel yapı sıfat tamlamasıdır. "Annemin" yalnızca sıfat-fiilin öznesidir.'),
  ('"Ağaç gövdesi" ile "ağacın gövdesi" arasındaki fark hangisidir?', 'İlki genel bir kavramı, ikincisi belli bir ağacı anlatır.', ['İkisi de aynı anlamdadır; yalnız yazımları farklıdır.', 'İlki belirli bir ağacı, ikincisi herhangi bir ağacı anlatır.', 'İlki sıfat tamlaması, ikincisi zincirleme tamlamadır.'], 'Belirtisiz tamlama türü ya da genel bir kavramı anlatır (ağaç gövdesi). Belirtili tamlamada tamlayan belirli bir varlığı gösterir (o ağacın gövdesi).'),
  ('Aşağıdaki Türkçe kökenli sözcüklerden hangisi büyük ünlü uyumuna uymaz?', 'elma', ['kapı', 'gözlük', 'yaprak'], '"Elma" sözcüğünde ince "e" ünlüsünden sonra kalın "a" gelmiştir. Türkçe olduğu hâlde uyuma aykırıdır; "anne" ve "kardeş" de böyledir.'),
  ('Aşağıdaki eklerden hangisi büyük ünlü uyumuna girmez?', '-yor', ['-ler', '-de', '-lik'], '"-yor" ekinin ünlüsü hiç değişmez; bu yüzden "geliyor, seviyor" gibi sözcüklerde uyum bozulur. "-ler, -de, -ci" ise sözcüğe göre biçim değiştirir.'),
  ('Küçük ünlü uyumuna göre a, e, ı, i ünlülerinden sonra hangi tür ünlüler gelir?', 'Düz ünlüler', ['Yuvarlak ünlüler', 'Yalnız dar yuvarlak ünlüler', 'Yalnız geniş yuvarlak ünlüler'], 'Küçük ünlü uyumu düzlük-yuvarlaklık uyumudur. Düz ünlüyü düz ünlüler izler; yuvarlak ünlüyü ise ya düz-geniş (a, e) ya da dar-yuvarlak (u, ü) ünlüler izler.'),
  ('Aşağıdaki Türkçe sözcüklerden hangisi küçük ünlü uyumuna uymaz?', 'yağmur', ['kırmızı', 'güzel', 'oyun'], '"Yağmur" sözcüğünde düz "a" ünlüsünden sonra yuvarlak "u" gelmiştir; bu küçük ünlü uyumuna aykırıdır. "Kavun, çamur, tavuk" da benzer istisnalardır.'),
  ('"Sabahleyin" sözcüğünde büyük ünlü uyumunun bozulmasının nedeni hangisidir?', 'Uyuma girmeyen bir ekin kullanılması', ['Kökün Arapçadan geçmiş yabancı bir sözcük olması', 'Sözcüğün birleşik olması', 'Sözcükte ünlü düşmesi olması'], '"-leyin" eki ünlü uyumlarına girmeyen ekler arasındadır. Bu yüzden kalın ünlülü "sabah" köküne ince ünlülü ek olarak gelmiştir.'),
  ('Aşağıdaki sözcüklerden hangisi hem büyük hem küçük ünlü uyumuna uyar?', 'bulut', ['kitap', 'otobüs', 'kardeş'], '"Bulut" sözcüğünde iki ünlü de kalın ve yuvarlaktır (u-u); iki uyum da sağlanır. "Kitap" ve "kardeş" büyük, "otobüs" de büyük ünlü uyumuna aykırıdır.'),
  ('"Geliyordu" sözcüğünde ek-fiil hangi görevi üstlenmiştir?', 'Basit zamanlı bir fiili birleşik zamanlı yapmıştır.', ['İsim soylu bir sözcüğü yüklem yapmıştır.', 'Fiili etken çatıdan edilgen çatıya dönüştürmüştür.', 'Fiile olumsuzluk anlamı katmıştır.'], '"Geliyor" şimdiki zamanlı basit bir fiildir; ek-fiilin "-du" biçimi onu şimdiki zamanın hikâyesi olan birleşik zamanlı bir fiile dönüştürmüştür.'),
  ('"O, bu okulun en deneyimli öğretmenidir." cümlesinde "-dir" eki hangi anlamı katmıştır?', 'Kesinlik', ['Öğrenilen geçmiş zaman', 'Koşul', 'İstek'], 'İsim soylu sözcüklere gelen "-dir" ek-fiili, yargıyı kesinlik ya da bilinen gerçek anlamıyla bildirir; ek-fiilin geniş zaman çekimidir.'),
  ('"Çocukken bu sokakta oynardık." cümlesindeki "çocukken" sözcüğünde bulunan "-ken" için hangisi doğrudur?', 'Ek-fiilin zarf-fiil biçimidir.', ['Bir çekim eki olan çoğul ekidir.', 'İsimden fiil yapan bir yapım ekidir.', 'Sözcüğü belirtili nesne yapan bir hâl ekidir.'], '"Çocuk iken" sözünden gelen "-ken", ek-fiilin zarf-fiil biçimidir. İsim soylu sözcüğe "o zamanlarda" anlamı katar.'),
  ('Altı öğrencinin bir ayda okuduğu kitap sayıları 2, 8, 5, 10, 6 ve 3\'tür. Bu verinin medyanı nedir?', '5,5', ['5', '6', '5,67'], 'Sıralanan veri: 2, 3, 5, 6, 8, 10. Çift sayıda veri olduğu için ortadaki iki değerin ortalaması alınır: (5+6)/2 = 5,5.'),
  ('1, 2, 3, 4 ve 100 sayılarından oluşan bir veri grubunda aritmetik ortalama ile ortanca arasındaki fark kaçtır?', '19', ['22', '3', '97'], 'Aritmetik ortalama (1+2+3+4+100)/5 = 22, ortanca 3\'tür. Fark 22 − 3 = 19\'dur. Uç değer ortalamayı büyük ölçüde etkilerken ortancayı etkilememiştir.'),
  ('Bir şirkette çalışanların çoğunun maaşı birbirine yakın, birkaç yöneticinin maaşı ise çok yüksektir. "Tipik" bir çalışanın maaşını göstermek için hangi ölçü daha uygundur?', 'Ortanca', ['Aritmetik ortalama', 'Açıklık', 'En büyük değer'], 'Çok yüksek birkaç değer aritmetik ortalamayı yukarı çeker. Ortanca ise sıralamanın ortasına baktığı için uç değerlerden çok az etkilenir.'),
  ('Bir ayakkabı mağazası, en çok satılan rengi belirleyip o renkten daha çok sipariş vermek istiyor. Bunun için hangi ölçüyü kullanmalıdır?', 'Tepe değer', ['Ortanca', 'Aritmetik ortalama', 'Açıklık'], 'Renk gibi sayısal olmayan verilerde ortalama ya da ortanca hesaplanamaz. En sık görülen değeri veren tepe değer bu iş için uygun ölçüdür.'),
  ('Bir veri grubundaki her sayıya 5 eklenirse aşağıdakilerden hangisi değişmez?', 'Açıklık', ['Aritmetik ortalama', 'Ortanca', 'Tepe değer'], 'Bütün değerler aynı miktarda kaydığı için en büyük ve en küçük değer de 5 artar; aralarındaki fark, yani açıklık aynı kalır. Ortalama, ortanca ve tepe değer 5 artar.'),
  ('A şehri, B şehrinden 7 saat ileridedir. A\'da saat 02.00 iken B\'de saat kaçtır?', 'Bir önceki günün 19.00\'u', ['Aynı günün 09.00\'u', 'Aynı günün 05.00\'i', 'Bir önceki günün 21.00\'i'], 'B geride olduğu için A\'daki saatten 7 saat çıkarılır: 02.00 − 7 saat, bir önceki günün 19.00\'u eder.'),
  ('Bir uçak X şehrinden yerel saatle 10.00\'da kalkıyor ve 4 saat uçuyor. Y şehri, X şehrinden 2 saat geride olduğuna göre uçak Y\'ye yerel saatle kaçta iner?', '12.00', ['14.00', '16.00', '8.00'], 'Uçak X saatine göre 14.00\'te iner. Y, X\'ten 2 saat geride olduğundan bu an Y\'de 12.00\'dir.'),
  ('Kasada yalnız 1, 5, 10, 25 ve 50 kuruşluk madeni paralar vardır. 88 kuruşluk para üstü en az kaç madeni parayla verilebilir?', '6', ['5', '7', '8'], 'En büyük paradan başlanır: 50 + 25 + 10 = 85 kuruş, kalan 3 kuruş üç tane 1 kuruşla verilir. Toplam 6 madeni para.'),
  ('Türkçedeki ünlülerden hangisi ince, dar ve yuvarlak ünlüdür?', 'ü', ['ö', 'ı', 'u ve o'], 'ü ince (dilin önüyle), dar (ağız az açık) ve yuvarlak (dudaklar yuvarlak) bir ünlüdür. ö geniş, u kalın, ı ise düz bir ünlüdür.'),
  ('Aşağıdaki sözcüklerden hangisinin tüm ünlüleri dar ünlüdür?', 'kuşu', ['gözü', 'kuzey', 'oyun'], 'Dar ünlüler ı, i, u, ü\'dür. "Kuşu" sözcüğündeki iki ünlü de u\'dur. Ötekilerde o, ö ya da e gibi geniş ünlüler vardır.'),
  ('"Birçok öğrenciler sınava geç kaldı." cümlesindeki anlatım bozukluğu nasıl giderilir?', '"öğrenciler" yerine "öğrenci" yazılarak', ['"birçok" yerine "birkaç" sözcüğü getirilerek', '"geç" sözcüğü çıkarılarak', '"sınava" yerine "sınavda" yazılarak'], '"Birçok" gibi çokluk bildiren belgisiz sıfatlardan sonra ad çoğul eki almaz: "birçok öğrenci".'),
  ('Aşağıdaki cümlelerin hangisinde "bu" ile birlikte kullanılan sözcük bitişik yazılmalıdır?', 'Bu gün hava çok güzel.', ['Bu akşam sinemaya gidelim.', 'Bu sabah erken kalktım.', 'Bu hafta çok yoğundu.'], 'İçinde bulunulan günü anlatan "bugün" kalıplaşmış bir sözcüktür ve bitişik yazılır. "Bu akşam, bu sabah, bu hafta" ise ayrı yazılır.'),
  ('"Halam hâlâ bizi bekliyor." cümlesinde "hâlâ" sözcüğündeki düzeltme işareti hangi amaçla kullanılmıştır?', 'Aynı yazılan iki sözcüğü ayırt etmek için', ['Sözcüğün yabancı kökenli olduğunu göstermek için', 'Sözcüğün vurgulu okunması gerektiğini belirtmek için', 'Ünlünün kısa okunduğunu göstermek için'], 'Düzeltme işareti, "hala" (babanın kız kardeşi) ile "hâlâ" (henüz, şimdiye kadar) gibi yazılışı aynı sözcükleri ayırt etmek için kullanılır.'),
  ('Aşağıdakilerin hangisinde nokta, kısaltmanın sonunu göstermek için kullanılmıştır?', 'Dr. Selin Hanım hastaları muayene etti.', ['Saat 14.30\'da buluşalım.', 'Yarışmada 3. olmuş.', 'Kentin o yılki nüfusu 1.250.000 kişiydi.'], '"Dr." kısaltmasından sonra nokta konmuştur. Öteki seçeneklerde nokta saat-dakika ayırmak, sıra sayısı göstermek ve basamakları gruplamak için kullanılmıştır.'),
  ('"-lık eki addan ad yapar." cümlesinde ekin başına konan kısa çizgi hangi amaçla kullanılmıştır?', 'Bir ekin ek olduğunu göstermek için', ['Sözcüğü satır sonunda bölmek için', 'Ara sözü ayırmak için', 'İki yer adı arasındaki ilişkiyi göstermek için'], 'Dil bilgisinde ekler, başlarına kısa çizgi konarak gösterilir: -lık, -de, -ci. Kökler ise fiil olduklarında sonlarına kısa çizgi alır: gel-.'),
  ('"Hangi kitabı okudun?" cümlesinde "hangi" sözcüğünün türü nedir?', 'Soru sıfatı', ['Soru zamiri', 'İşaret sıfatı', 'Belgisiz zamir'], '"Hangi" bir adın (kitap) önüne gelip onu soru yoluyla belirttiği için soru sıfatıdır. Tek başına adın yerini tutsaydı soru zamiri olurdu.'),
  ('"Kitabını hemen oku." ve "Kardeşin de gelsin." cümlelerinin yüklemleri hangi kiple çekimlenmiştir?', 'Emir kipi', ['İstek kipi', 'Gereklilik kipi', 'Şart kipi'], 'İkinci tekil kişide eki görünmeyen "oku" ile üçüncü tekil kişide "-sin" alan "gelsin" emir kipindedir.'),
  ('"Akşama kadar onu bekledik." cümlesinde "kadar" edatının kurduğu anlam ilgisi hangisidir?', 'Zaman sınırı', ['Benzerlik', 'Miktar karşılaştırması', 'Neden'], '"-e kadar" kalıbı burada bekleme eyleminin hangi zamana dek sürdüğünü, yani zaman sınırını gösterir.'),
  ('"Ali dün eve geldi." ile "Ali dün eve gelmiş." cümleleri arasındaki temel anlam farkı nedir?', 'İlkinde olay görülmüş, ikincisinde başkasından öğrenilmiştir.', ['İlkinde olay gelecekte, ikincisinde geçmişte gerçekleşir.', 'İkisi aynı anlamdadır; yalnız ekleri farklıdır.', 'İlkinde istek, ikincisinde gereklilik vardır.'], '"-di" görülen (bilinen) geçmiş zaman, "-miş" ise duyulan (öğrenilen) geçmiş zaman ekidir. Konuşan, ikinci cümlede olaya tanık olmadığını belirtir.'),
  ('"Kahvaltı yapmadan evden çıktı." cümlesindeki "yapmadan" fiilimsisi hangi anlamı verir?', 'Bir eylemin yapılmadığı durumda öteki eylemin gerçekleşmesi', ['İki eylemin karşılıklı yapılması', 'Bir eylemin yapılma amacı', 'Eylemin tekrar tekrar yapılması'], '"-madan" zarf-fiili, "yapmaksızın, yapmamış olarak" anlamı verir: çıkma eylemi kahvaltı yapılmamış bir durumda gerçekleşmiştir.'),
  ('"O, sınıfın en çalışkan öğrencisinden biridir." cümlesindeki anlatım bozukluğu nasıl giderilir?', '"öğrencisinden" yerine "öğrencilerinden" denir.', ['"en" sözcüğü cümleden çıkarılır.', '"biridir" yerine "birisidir" denir.', '"sınıfın" yerine "sınıfta" denir.'], '"Biri" sözcüğü bir topluluktan söz eder; bu yüzden ondan önceki ad çoğul olmalıdır: "en çalışkan öğrencilerinden biri".'),
  ('Aşağıdaki sözcüklerin hangisinde ünlüyle başlayan bir ek alındığı hâlde ünsüz yumuşaması olmamıştır?', 'topu', ['kitabı', 'ağacı', 'kanadı'], 'Tek heceli sözcüklerin çoğu yumuşamaz: top-topu, saç-saçı. Çok heceli sözcüklerde ise p-b, ç-c, t-d değişimi görülür.'),
  ('"Bayramda Ahmetler bize geldi." cümlesinde "-ler" eki hangi anlamı katmıştır?', 'Aile, birlikte yaşayan topluluk', ['Saygı', 'Abartma', 'Benzerlik'], 'Kişi adlarına gelen "-ler" eki, o kişiyi ve ailesini anlatabilir: Ahmetler = Ahmet ve ailesi.'),
  ('"Hava soğuk." gibi bir isim cümlesi olumsuz yapılırken yüklemden sonra hangi sözcük getirilir?', 'değil', ['yok', 'hayır', 'asla'], 'İsim soylu yüklemler "değil" sözcüğüyle olumsuz yapılır: "Hava soğuk değil." "Yok" ise varlığın olumsuzunu bildirir ve "var"ın karşıtıdır.'),
  ('Aşağıdaki cümlelerin hangisinin sonuna soru işareti konmaz?', 'Güzel mi güzel bir gün geçirdik', ['Bu akşam bize gelecek misin', 'Ödevini bitirdin mi', 'Kim aradı seni'], '"Güzel mi güzel" kalıbındaki "mi" pekiştirme görevindedir, soru sormaz. Bu yüzden cümlenin sonuna nokta konur.'),
];
